// Parse the AI Agent's raw text output into a real JSON object
const raw = $input.item.json.output;

let parsed;

try {
  // Strip markdown code fences if the model wrapped it in ```json ... ```
  const cleaned = raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  parsed = JSON.parse(cleaned);

} catch (e) {
  // Fallback if the model didn't return valid JSON
  parsed = {
    response: raw,
    reason: "The AI response could not be parsed as valid JSON.",
    human_handoff: false
  };
}

return {
  json: {
    response: parsed.response || "",
    reason: parsed.reason || "",
    human_handoff: parsed.human_handoff === true
  }
};
